insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A diligência de busca ou de apreensão será realizada por dois peritos nomeados pelo juiz, que verificarão a existência de fundamento para a apreensão, e, quer esta se realize, quer não, o laudo pericial será apresentado dentro de 3 dias após o encerramento da diligência. O requerente da diligência poderá impugnar o laudo contrário à apreensão, e o juiz ordenará que esta se efetue, se reconhecer a improcedência das razões dos peritos.', '["Busca ou apreensão por dois peritos nomeados pelo juiz.","Laudo em 3 dias após a diligência.","Impugnação do laudo contrário à apreensão; o juiz pode ordenar a apreensão."]'::jsonb, '["Prazo do laudo: 3 dias."]'::jsonb, 'Dois peritos verificam o fundamento da apreensão e entregam o laudo em 3 dias.', '["Assertiva que fixa em 10 dias o prazo do laudo dos peritos erra: são 3 dias."]'::jsonb, '[]'::jsonb, '["Art. 528"]'::jsonb, 'under_review', 'claude'
