insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes de ação privativa do ofendido, não será admitida queixa com fundamento em apreensão e em perícia, se decorrido o prazo de 30 dias, após a homologação do laudo. Será dada vista ao Ministério Público dos autos de busca e apreensão requeridas pelo ofendido, se o crime for de ação pública e não tiver sido oferecida queixa no prazo fixado neste artigo.', '["Ação privada: queixa com fundamento em apreensão e perícia no prazo de 30 dias da homologação do laudo.","Ação pública: vista ao MP se não houver queixa no prazo."]'::jsonb, '["Prazo de 30 dias da homologação do laudo."]'::jsonb, 'Passados 30 dias da homologação, não se admite mais a queixa baseada na apreensão.', '["Assertiva que fixa em 8 dias o prazo para a queixa nesse caso, fora do flagrante, erra: são 30 dias."]'::jsonb, '[]'::jsonb, '["Art. 530"]'::jsonb, 'under_review', 'claude'
