select u.id, u.content_sha256, 'O juiz, ao proferir a sentença condenatória, poderá determinar a destruição dos bens ilicitamente produzidos ou reproduzidos e o perdimento dos equipamentos apreendidos, desde que precipuamente destinados à produção e reprodução dos bens, em favor da Fazenda Nacional, que deverá destruí-los ou doá-los aos Estados, Municípios e Distrito Federal, a instituições públicas de ensino e pesquisa ou de assistência social, bem como incorporá-los, se houver interesse, ao patrimônio da União, que não poderá retorná-los aos canais de comércio.', '["Sentença condenatória: destruição dos bens ilícitos.","Perdimento dos equipamentos destinados precipuamente à produção.","Destino: Fazenda Nacional destrói, doa a entes e instituições ou incorpora ao patrimônio da União.","Não retornam aos canais de comércio."]'::jsonb, '["Os bens não podem voltar ao comércio."]'::jsonb, 'Na condenação, os equipamentos de reprodução são perdidos em favor da Fazenda Nacional.', '["Assertiva que permite o retorno dos bens ao comércio erra."]'::jsonb, '[]'::jsonb, '["Art. 530-F"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-530-g'
