select u.id, u.content_sha256, 'Aplica-se ao procedimento sumário o disposto nos parágrafos do art. 400 do Código. Os §§ 1º a 4º foram revogados.', '["Procedimento sumário segue os parágrafos do art. 400.","Parágrafos próprios revogados."]'::jsonb, '["Remissão ao art. 400."]'::jsonb, 'No rito sumário, as provas também são produzidas em uma só audiência.', '["Assertiva que mantém os parágrafos próprios do art. 533 em vigor erra."]'::jsonb, '[]'::jsonb, '["Art. 400"]'::jsonb, 'under_review', 'claude'
