insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No procedimento sumário, as alegações finais serão orais, concedendo-se a palavra, respectivamente, à acusação e à defesa, pelo prazo de 20 minutos, prorrogáveis por mais 10, proferindo o juiz, a seguir, sentença. Havendo mais de um acusado, o tempo previsto para a defesa de cada um será individual. Ao assistente do Ministério Público, após a manifestação deste, serão concedidos 10 minutos, prorrogando-se por igual período o tempo da defesa.', '["Alegações finais orais: 20 minutos, prorrogáveis por mais 10.","Acusação e defesa, nessa ordem; sentença em seguida.","Mais de um acusado: tempo individual.","Assistente: 10 minutos, com igual prorrogação para a defesa."]'::jsonb, '["Mesmos tempos do rito ordinário."]'::jsonb, 'No rito sumário, o juiz profere a sentença logo após as alegações orais.', '["Assertiva que fixa alegações finais por memoriais obrigatórios no rito sumário erra: são orais."]'::jsonb, '[]'::jsonb, '["Art. 403"]'::jsonb, 'under_review', 'claude'
