select u.id, u.content_sha256, 'A testemunha que comparecer será inquirida, independentemente da suspensão da audiência, observada em qualquer caso a ordem estabelecida no art. 531.', '["Testemunha presente é inquirida mesmo que a audiência esteja suspensa.","Respeita-se a ordem do art. 531."]'::jsonb, '["A ordem do art. 531 é mantida."]'::jsonb, 'A testemunha presente é ouvida, observada a ordem legal.', '["Assertiva que adia a inquirição da testemunha presente até a localização das demais erra."]'::jsonb, '[]'::jsonb, '["Art. 531"]'::jsonb, 'under_review', 'claude'
