insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas infrações penais de menor potencial ofensivo, quando o juizado especial criminal encaminhar ao juízo comum as peças existentes para a adoção de outro procedimento, observar-se-á o procedimento sumário previsto neste Capítulo. Os §§ 1º a 4º foram revogados.', '["Menor potencial ofensivo remetido ao juízo comum: procedimento sumário."]'::jsonb, '["Ocorre, por exemplo, quando o réu não é encontrado para citação no Juizado."]'::jsonb, 'O Juizado Especial remete as peças ao juízo comum, que adota o rito sumário.', '["Assertiva que adota o rito ordinário nesse caso erra: aplica-se o sumário."]'::jsonb, '[]'::jsonb, '["Art. 394"]'::jsonb, 'under_review', 'claude'
