insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os autos originais de processo penal extraviados ou destruídos, em primeira ou segunda instância, serão restaurados. Se existir e for exibida cópia autêntica ou certidão do processo, será uma ou outra considerada como original. Na falta, o juiz mandará, de ofício ou a requerimento, que o escrivão certifique o estado do processo segundo sua lembrança e reproduza o que houver nos protocolos; que sejam requisitadas cópias do que constar em institutos e repartições; e que as partes sejam citadas pessoalmente, ou por edital com o prazo de dez dias. A restauração será na primeira instância, ainda que os autos se tenham extraviado na segunda.', '["Autos extraviados ou destruídos são restaurados.","Cópia autêntica ou certidão vale como original.","Sem elas: certidão do escrivão, requisição de cópias e citação das partes (edital de dez dias).","Restauração na primeira instância."]'::jsonb, '["Edital de dez dias."]'::jsonb, 'Os autos são perdidos, e o escrivão certifica o estado do processo para a restauração.', '["Assertiva que fixa a restauração na segunda instância, se lá o extravio ocorreu, erra: ocorre na primeira."]'::jsonb, '[{"termo":"Restauração de autos","significado":"Procedimento para reconstituir autos perdidos ou destruídos."}]'::jsonb, '["Art. 542"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-541'
