select u.id, u.content_sha256, 'No dia designado, as partes serão ouvidas, mencionando-se em termo circunstanciado os pontos em que estiverem acordes e a exibição e a conferência das certidões e mais reproduções do processo apresentadas e conferidas.', '["Partes ouvidas no dia designado.","Termo circunstanciado: pontos de acordo e conferência das certidões e reproduções."]'::jsonb, '["Termo circunstanciado."]'::jsonb, 'No dia da restauração, as partes confirmam os pontos de acordo em termo.', '["Assertiva que dispensa o termo circunstanciado na restauração de autos erra."]'::jsonb, '[]'::jsonb, '["Art. 541"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-542'
