insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz determinará as diligências necessárias para a restauração, observando-se o seguinte: se ainda não foi proferida a sentença, reinquirir-se-ão as testemunhas, podendo ser substituídas as que tiverem falecido ou se encontrarem em lugar não sabido; os exames periciais, quando possível, serão repetidos, de preferência pelos mesmos peritos; a prova documental será reproduzida por cópia autêntica ou, quando impossível, por testemunhas; poderão ser inquiridas autoridades, serventuários, peritos e outras pessoas que tenham funcionado; e o Ministério Público e as partes poderão oferecer testemunhas e produzir documentos para provar o teor do processo extraviado ou destruído.', '["Reinquirição de testemunhas (substituição das que faleceram ou estão em local ignorado).","Repetição dos exames periciais, de preferência pelos mesmos peritos.","Prova documental por cópia autêntica ou testemunhas.","Oitiva de autoridades, serventuários e peritos que atuaram.","Partes produzem provas do teor do processo."]'::jsonb, '["Repetição, quando possível, das provas."]'::jsonb, 'Testemunhas são reinquiridas para reconstituir o processo.', '["Assertiva que dispensa a repetição de exames periciais na restauração erra."]'::jsonb, '[]'::jsonb, '["Art. 541"]'::jsonb, 'under_review', 'claude'
