select u.id, u.content_sha256, 'O Ministério Público, ao fazer o requerimento inicial, e a defesa, no prazo estabelecido no artigo anterior, poderão requerer exames, diligências e arrolar até três testemunhas.', '["MP e defesa podem requerer exames e diligências.","Arrolar até três testemunhas."]'::jsonb, '["Limite de três testemunhas."]'::jsonb, 'A defesa arrola três testemunhas e requer um exame.', '["Assertiva que fixa em cinco o número de testemunhas desse rito erra: são três."]'::jsonb, '[]'::jsonb, '["Art. 552"]'::jsonb, 'under_review', 'claude'
