insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Após o prazo de defesa ou a realização dos exames e diligências ordenados pelo juiz, de ofício ou a requerimento das partes, será marcada audiência, em que, inquiridas as testemunhas e produzidas alegações orais pelo Ministério Público e pelo defensor, dentro de dez minutos para cada um, o juiz proferirá sentença. Se o juiz não se julgar habilitado a proferir a decisão, designará, desde logo, outra audiência, que se realizará dentro de cinco dias, para publicar a sentença.', '["Audiência após o prazo de defesa e as diligências.","Alegações orais de dez minutos para cada parte.","Sentença proferida; se necessário, nova audiência em cinco dias para publicá-la."]'::jsonb, '["Dez minutos e, se necessário, cinco dias para publicar a sentença."]'::jsonb, 'O juiz designa nova audiência em cinco dias para publicar a sentença.', '["Assertiva que fixa em vinte minutos as alegações orais desse rito erra: são dez."]'::jsonb, '[]'::jsonb, '["Art. 555"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-554'
