insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando, instaurado processo por infração penal, o juiz, absolvendo ou impronunciando o réu, reconhecer a existência de qualquer dos fatos previstos nos arts. 14 ou 27 do Código Penal (redação original), aplicar-lhe-á, se for o caso, medida de segurança.', '["Absolvição ou impronúncia com reconhecimento de fato previsto nos arts. 14 ou 27 do CP.","Aplicação de medida de segurança, se for o caso."]'::jsonb, '["Dispositivo histórico ligado ao sistema anterior de medidas de segurança."]'::jsonb, 'Texto histórico, de aplicação rara hoje.', '["Assertiva que aplica o art. 555 sem considerar a reforma do Código Penal erra."]'::jsonb, '[]'::jsonb, '["Art. 549"]'::jsonb, 'under_review', 'claude'
