insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhum ato será declarado nulo, se da nulidade não resultar prejuízo para a acusação ou para a defesa (princípio pas de nullité sans grief).', '["Sem prejuízo, não há nulidade.","Vale para acusação e defesa."]'::jsonb, '["Exige a demonstração de prejuízo."]'::jsonb, 'Vício formal que não prejudicou a defesa não leva à nulidade.', '["Assertiva que declara nulidade sem demonstração de prejuízo erra, em regra."]'::jsonb, '[{"termo":"Pas de nullité sans grief","significado":"Não há nulidade sem prejuízo."}]'::jsonb, '["Art. 566"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-563'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A nulidade ocorrerá por incompetência, suspeição ou suborno do juiz; por ilegitimidade de parte; por falta das fórmulas ou dos termos como a denúncia ou a queixa e a representação, o exame do corpo de delito nos crimes que deixam vestígios, a nomeação de defensor ao réu presente que não tiver, a intervenção do Ministério Público em todos os termos da ação pública, a citação do réu, o interrogatório, os prazos, a sentença de pronúncia e as formalidades do Júri; por omissão de formalidade que constitua elemento essencial do ato; e por outras hipóteses previstas no dispositivo.', '["I: incompetência, suspeição ou suborno do juiz.","II: ilegitimidade de parte.","III: falta de fórmulas ou termos essenciais (denúncia, exame de corpo de delito, defensor, MP, citação, interrogatório, pronúncia, formalidades do Júri).","IV: omissão de formalidade essencial do ato."]'::jsonb, '["Nulidade relativa exige alegação oportuna e prejuízo; a absoluta pode ser reconhecida de ofício.","A redação do inciso III alude a institutos do Júri anteriores à reforma."]'::jsonb, 'A falta de citação do réu para ver-se processar gera nulidade.', '["Assertiva que não considera nulidade a falta de exame de corpo de delito nos crimes que deixam vestígios erra."]'::jsonb, '[]'::jsonb, '["Art. 563","Art. 572"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-564'
