insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhuma das partes poderá arguir nulidade a que haja dado causa, ou para que tenha concorrido, ou referente a formalidade cuja observância só à parte contrária interesse.', '["A parte não pode arguir nulidade que ela causou.","Nem a que só interessa à parte contrária."]'::jsonb, '["Vedação do venire contra factum proprium."]'::jsonb, 'A defesa não pode alegar nulidade que ela mesma provocou.', '["Assertiva que permite à parte alegar nulidade que ela mesma causou erra."]'::jsonb, '[]'::jsonb, '["Art. 563"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-565'
