insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não será declarada a nulidade de ato processual que não houver influído na apuração da verdade substancial ou na decisão da causa.', '["Sem influência na apuração da verdade ou na decisão, não se declara a nulidade."]'::jsonb, '["Outra face do princípio do prejuízo."]'::jsonb, 'Erro formal irrelevante para a decisão não anula o ato.', '["Assertiva que anula todo ato irregular, ainda que sem influência na decisão, erra."]'::jsonb, '[]'::jsonb, '["Art. 563"]'::jsonb, 'under_review', 'claude'
