insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A incompetência do juízo anula somente os atos decisórios, devendo o processo, quando for declarada a nulidade, ser remetido ao juiz competente.', '["Incompetência anula somente os atos decisórios.","O processo segue ao juiz competente."]'::jsonb, '["Atos instrutórios podem ser aproveitados (teoria prevalente, ainda que a jurisprudência distinga a incompetência absoluta)."]'::jsonb, 'Declarada a incompetência, as decisões são anuladas e o processo vai ao juízo competente.', '["Assertiva que anula todos os atos do processo, incluindo a instrução, na incompetência, erra segundo a letra do art. 567."]'::jsonb, '[]'::jsonb, '["Art. 108"]'::jsonb, 'under_review', 'claude'
