insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As omissões da denúncia ou da queixa, da representação, ou, nos processos das contravenções penais, da portaria ou do auto de prisão em flagrante, poderão ser supridas a todo o tempo, antes da sentença final.', '["Omissões da denúncia, queixa ou representação são supridas até a sentença."]'::jsonb, '["Limite: antes da sentença final."]'::jsonb, 'O MP supre uma omissão da denúncia antes da sentença.', '["Assertiva que impede suprir omissões da denúncia após o recebimento erra."]'::jsonb, '[]'::jsonb, '["Art. 564"]'::jsonb, 'under_review', 'claude'
