on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A falta ou a nulidade da citação, da intimação ou notificação estará sanada, desde que o interessado compareça antes de o ato consumar-se, embora declare que o faz para o único fim de arguí-la. O juiz ordenará, todavia, a suspensão ou o adiamento do ato, quando reconhecer que a irregularidade poderá prejudicar direito da parte.', '["Comparecimento do interessado sana a falta ou nulidade da citação, intimação ou notificação.","Mesmo que compareça apenas para arguir.","O juiz suspende ou adia o ato se houver risco de prejuízo."]'::jsonb, '["Comparecimento = sanação (com ressalva de prejuízo)."]'::jsonb, 'O réu comparece mesmo sem citação válida: a nulidade é sanada, salvo risco de prejuízo.', '["Assertiva que mantém a nulidade da citação mesmo com o comparecimento do réu erra."]'::jsonb, '[]'::jsonb, '["Art. 572"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-570'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As nulidades deverão ser arguidas: as da instrução criminal dos processos do júri, nos prazos do art. 406; as da instrução dos processos do juiz singular e dos especiais, nos prazos do art. 500; as do processo sumário, no prazo do art. 537 ou logo depois de aberta a audiência e apregoadas as partes; as ocorridas posteriormente à pronúncia, logo depois de anunciado o julgamento e apregoadas as partes; as de instrução dos processos de competência do STF e dos tribunais, nos prazos do art. 500; as verificadas após a decisão de primeira instância, nas razões de recurso ou logo depois de anunciado o julgamento do recurso; e as do julgamento em plenário, em audiência ou em sessão do tribunal, logo depois de ocorrerem.', '["Momentos de arguição variam conforme o rito e a fase.","Nulidades do plenário e de sessões: logo depois de ocorrerem.","Pós-pronúncia: logo depois de anunciado o julgamento.","Após a decisão de primeira instância: nas razões do recurso."]'::jsonb, '["Preclusão: a nulidade relativa não alegada a tempo fica sanada."]'::jsonb, 'A nulidade ocorrida no plenário deve ser arguida logo depois de ocorrer.', '["Assertiva que permite arguir qualquer nulidade ao final do processo, sem preclusão, erra."]'::jsonb, '[{"termo":"Preclusão","significado":"Perda da oportunidade processual por não exercê-la no momento certo."}]'::jsonb, '["Art. 572"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-571'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As nulidades previstas no art. 564, III, d e e (segunda parte), g e h, e IV, considerar-se-ão sanadas se não forem arguidas em tempo oportuno, de acordo com o artigo anterior; se, praticado o ato por outra forma, tiver atingido o seu fim; ou se a parte, ainda que tacitamente, tiver aceito os seus efeitos.', '["Sanam-se se não forem arguidas a tempo.","Sanam-se se o ato atingiu seu fim por outra forma.","Sanam-se se a parte aceitou seus efeitos, ainda que tacitamente."]'::jsonb, '["Três formas de sanação."]'::jsonb, 'O ato praticado de outra forma atingiu sua finalidade: nulidade sanada.', '["Assertiva que torna insanáveis essas nulidades erra: elas se sanam nas três hipóteses do art. 572."]'::jsonb, '[]'::jsonb, '["Art. 571"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-572'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os atos cuja nulidade não tiver sido sanada serão renovados ou retificados. A nulidade de um ato, uma vez declarada, causará a dos atos que dele diretamente dependam ou sejam consequência. O juiz que pronunciar a nulidade declarará os atos a que ela se estende.', '["Atos nulos não sanados são renovados ou retificados.","Nulidade contamina os atos dependentes ou consequentes (nulidade derivada).","O juiz declara os atos a que a nulidade se estende."]'::jsonb, '["Nulidade por derivação."]'::jsonb, 'A nulidade da citação atinge os atos posteriores dela dependentes.', '["Assertiva que limita a nulidade ao ato viciado, sem alcançar os dependentes, erra."]'::jsonb, '[]'::jsonb, '["Art. 564"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-573'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os recursos serão voluntários, excetuando-se os casos em que deverão ser interpostos, de ofício, pelo juiz: da sentença que conceder habeas corpus e da que absolver desde logo o réu com fundamento na existência de circunstância que exclua o crime ou isente o réu de pena, nos termos do art. 411 (hipótese da absolvição sumária no Júri).', '["Regra: recursos voluntários.","Recurso de ofício: sentença que concede habeas corpus.","Recurso de ofício: absolvição sumária por excludente de crime ou isenção de pena."]'::jsonb, '["O recurso de ofício da absolvição sumária no Júri foi retirado pela reforma de 2008; a referência é histórica."]'::jsonb, 'A concessão de habeas corpus sujeita-se a recurso de ofício.', '["Assertiva que torna obrigatórios todos os recursos erra: a regra é a voluntariedade."]'::jsonb, '[{"termo":"Recurso de ofício","significado":"Reexame necessário imposto ao juiz."}]'::jsonb, '["Art. 581"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-574'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não serão prejudicados os recursos que, por erro, falta ou omissão dos funcionários, não tiverem seguimento ou não forem apresentados dentro do prazo.', '["Falha dos funcionários não prejudica o recurso."]'::jsonb, '["Proteção da parte contra erro do serviço judiciário."]'::jsonb, 'O recurso não subiu por omissão do cartório, e a parte não é prejudicada.', '["Assertiva que prejudica a parte por erro dos funcionários da justiça erra."]'::jsonb, '[]'::jsonb, '["Art. 586"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-575'
