insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Ministério Público não poderá desistir de recurso que haja interposto.', '["MP não desiste de recurso interposto (indisponibilidade)."]'::jsonb, '["Coerência com o art. 42."]'::jsonb, 'Interposta a apelação, o MP não pode desistir dela.', '["Assertiva que permite ao MP desistir do recurso que interpôs erra."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
