insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O recurso poderá ser interposto pelo Ministério Público, ou pelo querelante, ou pelo réu, seu procurador ou seu defensor. Não se admitirá, entretanto, recurso da parte que não tiver interesse na reforma ou modificação da decisão.', '["Legitimados: MP, querelante, réu, procurador ou defensor.","Exige interesse na reforma ou modificação."]'::jsonb, '["Interesse recursal."]'::jsonb, 'O réu absolvido não tem interesse em recorrer da absolvição.', '["Assertiva que dispensa o interesse recursal erra."]'::jsonb, '[]'::jsonb, '["Art. 578"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-577'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O recurso será interposto por petição ou por termo nos autos, assinado pelo recorrente ou por seu representante. Não sabendo ou não podendo o réu assinar o nome, o termo será assinado por alguém, a seu rogo, na presença de duas testemunhas. A petição de interposição, com o despacho do juiz, será, até o dia seguinte ao último do prazo, entregue ao escrivão, que certificará no termo da juntada a data da entrega. Interposto por termo o recurso, o escrivão, sob pena de suspensão por dez a trinta dias, fará conclusos os autos ao juiz, até o dia seguinte ao último do prazo.', '["Interposição por petição ou termo nos autos.","Réu que não sabe assinar: alguém assina a rogo, com duas testemunhas.","Petição entregue ao escrivão até o dia seguinte ao último do prazo.","Escrivão faz os autos conclusos até o dia seguinte ao último do prazo, sob pena de suspensão."]'::jsonb, '["Duas testemunhas na assinatura a rogo."]'::jsonb, 'O réu analfabeto interpõe o recurso por termo, assinado a rogo na presença de duas testemunhas.', '["Assertiva que dispensa testemunhas na assinatura a rogo do réu erra."]'::jsonb, '[]'::jsonb, '["Art. 586"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-578'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Salvo a hipótese de má-fé, a parte não será prejudicada pela interposição de um recurso por outro (princípio da fungibilidade). Se o juiz, desde logo, reconhecer a impropriedade do recurso interposto, mandará processá-lo de acordo com o rito do recurso cabível.', '["Fungibilidade recursal, salvo má-fé.","O juiz manda processar pelo rito do recurso cabível."]'::jsonb, '["A má-fé afasta a fungibilidade."]'::jsonb, 'Apelação interposta no lugar do recurso em sentido estrito é processada pelo rito correto.', '["Assertiva que aplica a fungibilidade mesmo em caso de má-fé erra."]'::jsonb, '[{"termo":"Fungibilidade","significado":"Aproveitamento de um recurso por outro."}]'::jsonb, '["Art. 581"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-579'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso de concurso de agentes (art. 25 do Código Penal), a decisão do recurso interposto por um dos réus, se fundado em motivos que não sejam de caráter exclusivamente pessoal, aproveitará aos outros.', '["Concurso de agentes: o recurso de um aproveita aos demais.","Desde que o fundamento não seja exclusivamente pessoal."]'::jsonb, '["Efeito extensivo do recurso."]'::jsonb, 'A absolvição por inexistência do fato, obtida por um corréu, aproveita aos outros.', '["Assertiva que nega o efeito extensivo mesmo quando os motivos não são pessoais erra."]'::jsonb, '[{"termo":"Efeito extensivo","significado":"O resultado do recurso de um beneficia os corréus."}]'::jsonb, '["Art. 581"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-580'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Caberá recurso, no sentido estrito, da decisão, despacho ou sentença que não receber a denúncia ou a queixa; que concluir pela incompetência do juízo; que julgar procedentes as exceções, salvo a de suspeição; que pronunciar o réu; que conceder, negar, arbitrar, cassar ou julgar inidônea a fiança, indeferir requerimento de prisão preventiva ou revogá-la, conceder liberdade provisória ou relaxar a prisão em flagrante; que julgar quebrada a fiança ou perdido o seu valor; que decretar a prescrição ou julgar, por outro modo, extinta a punibilidade; que indeferir o pedido de reconhecimento da prescrição ou de outra causa extintiva; que conceder ou negar habeas corpus; que conceder, negar ou revogar a suspensão condicional da pena; que conceder, negar ou revogar livramento condicional; que anular o processo da instrução criminal, no todo ou em parte; que incluir jurado na lista geral ou dela o excluir; que denegar a apelação ou a julgar deserta; que ordenar a suspensão do processo em virtude de questão prejudicial; entre outras hipóteses.', '["I: não receber denúncia ou queixa.","II: incompetência do juízo.","III: exceções procedentes (salvo suspeição).","IV: pronúncia.","V: fiança, preventiva, liberdade provisória e relaxamento.","VII e VIII: fiança quebrada; extinção da punibilidade.","X: habeas corpus; XI e XII: sursis e livramento.","XIII: anulação da instrução; XIV: lista de jurados.","XV: denegar apelação; XVI: questão prejudicial."]'::jsonb, '["Rol é taxativo, mas admite interpretação extensiva (STF/STJ).","Contra a impronúncia e a absolvição sumária cabe apelação (art. 416)."]'::jsonb, 'Contra a decisão que rejeita a denúncia, cabe recurso em sentido estrito.', '["Assertiva que prevê apelação contra a decisão de pronúncia erra: cabe recurso em sentido estrito."]'::jsonb, '[]'::jsonb, '["Art. 582","Art. 416"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-581'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os recursos em sentido estrito serão sempre para o Tribunal de Apelação, salvo nos casos dos incisos V, X e XIV. O recurso, no caso do inciso XIV (lista de jurados), será para o presidente do Tribunal de Apelação.', '["Regra: Tribunal de Apelação.","Exceções: incisos V, X e XIV do art. 581.","Inciso XIV (lista de jurados): para o presidente do Tribunal."]'::jsonb, '["Texto anterior à organização atual dos tribunais."]'::jsonb, 'O recurso contra a inclusão de jurado na lista vai ao presidente do tribunal.', '["Assertiva que envia todos os recursos em sentido estrito ao presidente do tribunal erra."]'::jsonb, '[]'::jsonb, '["Art. 581"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-582'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Subirão nos próprios autos os recursos interpostos de ofício; nos casos do art. 581, I, III, IV, VI, VIII e X; e quando o recurso não prejudicar o andamento do processo. O recurso da pronúncia subirá em traslado quando, havendo dois ou mais réus, qualquer deles se conformar com a decisão ou todos não tiverem sido ainda intimados.', '["Sobem nos próprios autos: recursos de ofício, os de certos incisos do art. 581 e os que não prejudicam o andamento.","Pronúncia: sobe em traslado se houver mais de um réu e um se conformar ou nem todos forem intimados."]'::jsonb, '["Instrumento (traslado) × próprios autos."]'::jsonb, 'O recurso contra a pronúncia sobe em traslado quando um dos réus se conforma.', '["Assertiva que manda subir sempre em traslado o recurso da pronúncia erra."]'::jsonb, '[]'::jsonb, '["Art. 587"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-583'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os recursos terão efeito suspensivo nos casos de perda da fiança, de concessão de livramento condicional e dos incisos XV, XVII e XXIV do art. 581. Ao recurso de sentença de impronúncia ou no caso do inciso VIII do art. 581, aplica-se o disposto nos arts. 596 e 598. O recurso da pronúncia suspenderá tão somente o julgamento. O recurso do despacho que julgar quebrada a fiança suspenderá unicamente o efeito de perda da metade do seu valor. No caso do inciso V do art. 581, o recorrente poderá pedir ao Tribunal, a qualquer tempo, até o julgamento, a concessão de efeito suspensivo ou ativo ao recurso, demonstrando a relevância dos motivos, a plausibilidade do direito alegado e a probabilidade de dano.', '["Efeito suspensivo: perda da fiança, livramento condicional e certos incisos do art. 581.","Pronúncia: suspende apenas o julgamento.","Fiança quebrada: suspende só a perda de metade do valor.","Inciso V: possibilidade de pedir efeito suspensivo ou ativo ao tribunal."]'::jsonb, '["Efeito suspensivo restrito."]'::jsonb, 'O recurso da pronúncia suspende o julgamento pelo Júri.', '["Assertiva que atribui efeito suspensivo amplo ao recurso em sentido estrito erra."]'::jsonb, '[]'::jsonb, '["Art. 581"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-584'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O réu não poderá recorrer da pronúncia senão depois de preso, salvo se prestar fiança, nos casos em que a lei a admitir. O dispositivo é considerado superado, pois a Constituição e a legislação posterior vedam condicionar o recurso ao recolhimento à prisão.', '["Previa que o recurso da pronúncia dependia da prisão do réu ou de fiança.","Considerado superado."]'::jsonb, '["Dispositivo superado: o recurso independe da prisão."]'::jsonb, 'Hoje, o réu solto pode recorrer da pronúncia.', '["Assertiva que exige a prisão do réu para recorrer da pronúncia erra."]'::jsonb, '[]'::jsonb, '["Art. 581, IV"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-585'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O recurso voluntário poderá ser interposto no prazo de cinco dias. No caso do art. 581, XIV (lista de jurados), o prazo será de vinte dias, contado da data da publicação definitiva da lista de jurados.', '["Prazo geral do recurso em sentido estrito: cinco dias.","Lista de jurados: vinte dias, da publicação definitiva."]'::jsonb, '["Cinco dias; vinte dias para a lista de jurados."]'::jsonb, 'A parte tem cinco dias para interpor o recurso em sentido estrito.', '["Assertiva que fixa em dez dias o prazo do recurso em sentido estrito erra: são cinco dias."]'::jsonb, '[]'::jsonb, '["Art. 581"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-586'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando o recurso houver de subir por instrumento, a parte indicará, no respectivo termo ou em requerimento avulso, as peças dos autos de que pretenda traslado. O traslado será extraído, conferido e concertado no prazo de cinco dias, e dele constarão sempre a decisão recorrida, a certidão de sua intimação, se por outra forma não for possível verificar a oportunidade do recurso, e o termo de interposição.', '["Recurso por instrumento: a parte indica as peças a transladar.","Traslado extraído e conferido em cinco dias.","Constam sempre a decisão recorrida, a certidão da intimação e o termo de interposição."]'::jsonb, '["Peças obrigatórias do traslado."]'::jsonb, 'A parte indica as peças que quer ver transladadas no recurso por instrumento.', '["Assertiva que dispensa a decisão recorrida no traslado erra."]'::jsonb, '[]'::jsonb, '["Art. 583"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-587'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Dentro de dois dias, contados da interposição do recurso, ou do dia em que o escrivão, extraído o traslado, o fizer com vista ao recorrente, este oferecerá as razões e, em seguida, será aberta vista ao recorrido por igual prazo. Se o recorrido for o réu, será intimado do prazo na pessoa do defensor.', '["Razões do recorrente em dois dias.","Contrarrazões do recorrido por igual prazo.","Réu recorrido: intimado na pessoa do defensor."]'::jsonb, '["Prazo de dois dias para razões e contrarrazões."]'::jsonb, 'O recorrente apresenta as razões em dois dias, e o recorrido, em igual prazo.', '["Assertiva que fixa em cinco dias as razões do recurso em sentido estrito erra: são dois dias."]'::jsonb, '[]'::jsonb, '["Art. 589"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-588'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Com a resposta do recorrido ou sem ela, será o recurso concluso ao juiz, que, dentro de dois dias, reformará ou sustentará o seu despacho, mandando instruir o recurso com os traslados que lhe parecerem necessários. Se o juiz reformar o despacho recorrido, a parte contrária, por simples petição, poderá recorrer da nova decisão, se couber recurso, não sendo mais lícito ao juiz modificá-la. Neste caso, independentemente de novos arrazoados, subirá o recurso nos próprios autos ou em traslado.', '["Juiz tem dois dias para reformar ou sustentar a decisão (juízo de retratação).","Reformada a decisão: a parte contrária pode recorrer por simples petição.","Não se admite nova modificação pelo juiz."]'::jsonb, '["Juízo de retratação no recurso em sentido estrito."]'::jsonb, 'O juiz se retrata em dois dias, e a parte contrária recorre da nova decisão por simples petição.', '["Assertiva que veda ao juiz reformar sua decisão no recurso em sentido estrito erra: há juízo de retratação."]'::jsonb, '[{"termo":"Juízo de retratação","significado":"Possibilidade de o juiz reformar a própria decisão."}]'::jsonb, '["Art. 588"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-589'
