insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Caberá apelação no prazo de 5 dias das sentenças definitivas de condenação ou absolvição proferidas por juiz singular; das decisões definitivas, ou com força de definitivas, proferidas por juiz singular nos casos não previstos no Capítulo anterior (recurso em sentido estrito); e das decisões do Tribunal do Júri quando ocorrer nulidade posterior à pronúncia; for a sentença do juiz-presidente contrária à lei expressa ou à decisão dos jurados; houver erro ou injustiça no tocante à aplicação da pena ou da medida de segurança; ou for a decisão dos jurados manifestamente contrária à prova dos autos. Se a sentença do juiz-presidente for contrária à lei expressa ou divergir das respostas dos jurados, o tribunal fará a devida retificação.', '["I: sentenças definitivas do juiz singular.","II: decisões definitivas ou com força de definitivas, fora do rol do recurso em sentido estrito.","III: Júri: nulidade posterior à pronúncia; sentença contrária à lei ou à decisão dos jurados; erro ou injustiça na pena; decisão manifestamente contrária à prova.","Prazo de 5 dias."]'::jsonb, '["Apelação contra o Júri tem fundamentos TAXATIVOS (alíneas a a d).","Apelação: 5 dias."]'::jsonb, 'Decisão dos jurados manifestamente contrária à prova dos autos desafia apelação.', '["Assertiva que admite apelação contra o Júri por qualquer motivo erra: os fundamentos do inciso III são taxativos."]'::jsonb, '[]'::jsonb, '["Art. 581","Art. 600"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-593'
