insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A apelação da sentença absolutória não impedirá que o réu seja posto imediatamente em liberdade. A apelação não suspenderá a execução da medida de segurança aplicada provisoriamente.', '["Apelação da absolvição não impede a liberdade imediata do réu.","Apelação não suspende a medida de segurança provisória."]'::jsonb, '["Absolvição: liberdade imediata."]'::jsonb, 'O réu absolvido é solto, mesmo que o MP apele.', '["Assertiva que mantém o réu preso até o julgamento da apelação contra a absolvição erra."]'::jsonb, '[]'::jsonb, '["Art. 597"]'::jsonb, 'under_review', 'claude'
