insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A apelação de sentença condenatória terá efeito suspensivo, salvo o disposto no art. 393, a aplicação provisória de interdições de direitos e de medidas de segurança (arts. 374 e 378), e o caso de suspensão condicional de pena.', '["Apelação da condenação tem efeito suspensivo, em regra.","Ressalvas: aplicação provisória de interdições e de medidas de segurança, e suspensão condicional da pena."]'::jsonb, '["Efeito suspensivo não impede a prisão preventiva fundamentada."]'::jsonb, 'Apelação da condenação suspende os efeitos da sentença, salvo as ressalvas legais.', '["Assertiva que nega efeito suspensivo à apelação da sentença condenatória em qualquer hipótese erra."]'::jsonb, '[]'::jsonb, '["Art. 596"]'::jsonb, 'under_review', 'claude'
