insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes de competência do Tribunal do Júri, ou do juiz singular, se da sentença não for interposta apelação pelo Ministério Público no prazo legal, o ofendido ou qualquer das pessoas enumeradas no art. 31, ainda que não se tenha habilitado como assistente, poderá interpor apelação, que não terá, porém, efeito suspensivo. O prazo para interposição desse recurso será de quinze dias e correrá do dia em que terminar o do Ministério Público.', '["Apelação supletiva do ofendido ou legitimados do art. 31.","Cabe se o MP não apelar no prazo legal.","Sem efeito suspensivo.","Prazo de quinze dias, a contar do fim do prazo do MP."]'::jsonb, '["Ofendido NÃO habilitado como assistente tem quinze dias, a contar do fim do prazo do MP."]'::jsonb, 'O MP não apela, e a vítima, não habilitada, apela em quinze dias.', '["Assertiva que fixa em cinco dias o prazo da apelação supletiva do ofendido não habilitado erra: são quinze dias."]'::jsonb, '[]'::jsonb, '["Art. 31","Art. 271"]'::jsonb, 'under_review', 'claude'
