insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Assinado o termo de apelação, o apelante e, depois dele, o apelado terão o prazo de oito dias cada um para oferecer razões, salvo nos processos de contravenção, em que o prazo será de três dias. Se houver assistente, este arrazoará, no prazo de três dias, após o Ministério Público. Se a ação penal for movida pela parte ofendida, o Ministério Público terá vista dos autos no mesmo prazo. Quando forem dois ou mais os apelantes ou apelados, os prazos serão comuns. Se o apelante declarar, na petição ou no termo, que deseja arrazoar na superior instância, os autos serão remetidos ao tribunal ad quem, onde será aberta vista às partes.', '["Razões: oito dias para cada parte (contravenção: três dias).","Assistente: três dias após o MP.","Ação privada: MP tem vista no mesmo prazo.","Vários apelantes ou apelados: prazos comuns.","Razões na instância superior, se o apelante declarar."]'::jsonb, '["Oito dias para as razões; três para contravenção e assistente."]'::jsonb, 'O apelante tem oito dias para apresentar as razões, e o apelado, outros oito.', '["Assertiva que fixa em cinco dias o prazo das razões de apelação erra: são oito dias."]'::jsonb, '[]'::jsonb, '["Art. 593","Art. 601"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-600'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Findos os prazos para razões, os autos serão remetidos à instância superior, com as razões ou sem elas, no prazo de 5 dias, salvo no caso do art. 603, segunda parte, em que o prazo será de trinta dias. Se houver mais de um réu, e não houverem todos sido julgados, ou não tiverem todos apelado, caberá ao apelante promover a extração do traslado dos autos, o qual deverá ser remetido à instância superior no prazo de trinta dias. As despesas do traslado correrão por conta de quem o solicitar, salvo se o pedido for de réu pobre ou do Ministério Público.', '["Remessa à instância superior em cinco dias após as razões.","Exceção do art. 603, segunda parte: trinta dias.","Vários réus: traslado promovido pelo apelante, em trinta dias.","Despesas por conta de quem solicitar, salvo réu pobre ou MP."]'::jsonb, '["Cinco dias (regra) e trinta dias (traslado)."]'::jsonb, 'Findo o prazo das razões, os autos sobem ao tribunal em cinco dias.', '["Assertiva que cobra as despesas do traslado do réu pobre erra."]'::jsonb, '[]'::jsonb, '["Art. 600","Art. 603"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-601'
