select u.id, u.content_sha256, 'A apelação subirá nos autos originais e, a não ser no Distrito Federal e nas comarcas que forem sede de Tribunal de Apelação, ficará em cartório traslado dos termos essenciais do processo referidos no art. 564, III.', '["Apelação sobe nos autos originais.","Ficam em cartório traslados dos termos essenciais (art. 564, III), salvo nas sedes de tribunal."]'::jsonb, '["Traslado dos termos essenciais fica em cartório."]'::jsonb, 'Os autos originais sobem, e o cartório conserva o traslado dos termos essenciais.', '["Assertiva que manda enviar ao tribunal apenas o traslado, mantendo os originais em cartório, erra."]'::jsonb, '[]'::jsonb, '["Art. 564","Art. 601"]'::jsonb, 'under_review', 'claude'
