insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os recursos, apelações e embargos serão julgados pelos Tribunais de Justiça, câmaras ou turmas criminais, de acordo com a competência estabelecida nas leis de organização judiciária. Quando não for unânime a decisão de segunda instância desfavorável ao réu, admitem-se embargos infringentes e de nulidade, que poderão ser opostos dentro de 10 dias, a contar da publicação do acórdão. Se o desacordo for parcial, os embargos serão restritos à matéria objeto de divergência.', '["Recursos julgados por Tribunais de Justiça, câmaras ou turmas criminais.","Decisão não unânime desfavorável ao réu: embargos infringentes e de nulidade.","Prazo de 10 dias da publicação do acórdão.","Divergência parcial: embargos restritos à matéria divergente."]'::jsonb, '["Embargos infringentes: só em favor do réu e se a decisão não for unânime.","Prazo de 10 dias."]'::jsonb, 'Voto vencido favorável ao réu permite os embargos infringentes em 10 dias.', '["Assertiva que admite embargos infringentes em favor da acusação erra: apenas em favor do réu."]'::jsonb, '[{"termo":"Embargos infringentes","significado":"Recurso contra decisão não unânime desfavorável ao réu."}]'::jsonb, '["Art. 613"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-609'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos recursos em sentido estrito, com exceção do de habeas corpus, e nas apelações interpostas das sentenças em processo de contravenção ou de crime a que a lei comine pena de detenção, os autos irão imediatamente com vista ao procurador-geral pelo prazo de cinco dias e, em seguida, passarão, por igual prazo, ao relator, que pedirá designação de dia para o julgamento. Anunciado o julgamento e apregoadas as partes, o relator fará a exposição do feito e o presidente concederá, pelo prazo de 10 minutos, a palavra aos advogados ou às partes que a solicitarem e ao procurador-geral, quando o requerer, por igual prazo.', '["Recursos em sentido estrito (exceto habeas corpus) e apelações em contravenção ou crime com detenção.","Vista ao procurador-geral por cinco dias e depois ao relator por igual prazo.","Sustentação oral de 10 minutos."]'::jsonb, '["Rito da detenção: sem revisor.","Sustentação oral: 10 minutos."]'::jsonb, 'Em apelação de crime punido com detenção, os autos vão ao procurador-geral e depois ao relator.', '["Assertiva que prevê revisor no rito de apelação de crime punido com detenção erra."]'::jsonb, '[]'::jsonb, '["Art. 613"]'::jsonb, 'under_review', 'claude'
