insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os recursos de habeas corpus, designado o relator, serão julgados na primeira sessão.', '["Recursos de habeas corpus são julgados na primeira sessão após a designação do relator."]'::jsonb, '["Celeridade do habeas corpus."]'::jsonb, 'Designado o relator, o recurso de habeas corpus é julgado na primeira sessão.', '["Assertiva que submete o recurso de habeas corpus ao rito comum, sem preferência, erra."]'::jsonb, '[]'::jsonb, '["Art. 647"]'::jsonb, 'under_review', 'claude'
