on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As apelações interpostas das sentenças proferidas em processos por crime a que a lei comine pena de reclusão deverão ser processadas e julgadas pela forma estabelecida no art. 610, com as seguintes modificações: exarado o relatório nos autos, passarão estes ao revisor, que terá igual prazo para o exame do processo e pedirá designação de dia para o julgamento; os prazos serão ampliados ao dobro; e o tempo para os debates será de um quarto de hora.', '["Apelação em crime de reclusão segue o art. 610 com modificações.","Há revisor.","Prazos em dobro.","Debates de um quarto de hora."]'::jsonb, '["Reclusão: revisor, prazos em dobro e quinze minutos de debate."]'::jsonb, 'A apelação de crime punido com reclusão tem revisor e prazos em dobro.', '["Assertiva que dispensa revisor na apelação de crime punido com reclusão erra."]'::jsonb, '[]'::jsonb, '["Art. 610"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-613'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

